mapper.sql:
where p.clan_id = #{criteria.clanId}
  and p.deleted_at is null
  and lower(p.name) = #{criteria.normalizedName}

    and p.branch_id = #{criteria.branchId}


    and p.generation_no = #{criteria.generationNo}


    and p.generation_word = #{criteria.generationWord}


    and p.birth_date = #{criteria.birthDate}

mapper.select:
select p.created_at::date as created_day,
       count(*) as created_count
from person p
where p.clan_id = #{clanId}
  and p.data_status = #{dataStatus}
  and p.deleted_at is null
  and p.created_at >= #{fromTime}
group by p.created_at::date
order by p.created_at::date

select 
from person p
where p.clan_id = #{clanId}
  and p.data_status = #{dataStatus}
  and p.deleted_at is null
order by p.updated_at desc nulls last,
         p.created_at desc nulls last,
         p.id desc
limit #{limit}
